<?php

declare(strict_types=1);

namespace AIC\Component\Application\Templates;

use AIC\Component\Application\ComponentTemplates;
use AIC\Component\Application\RenderPass;
use AIC\Component\Contracts\Component;
use AIC\Component\Exception\UnknownComponent;
use AIC\Profiler\Domain\ProfilerDebug;
use Override;

/**
 * Generated by composer run build from framework/templates/components (#92): the template lookup (#98).
 * Do not edit; change the manifest and run composer run build.
 */
final readonly class AtomTemplatesPart7 implements ComponentTemplates
{
    /**
     * @param Component  $component  A component.
     * @param RenderPass $renderPass The pass rendering it.
     *
     * @throws UnknownComponent When no template renders it.
     *
     * @return string Its markup: the declared library atoms.
     */
    #[Override]
    public function compose(Component $component, RenderPass $renderPass): string
    {
        return match (true) {
            $component instanceof ProfilerDebug => $this->renderProfilerDebug($component, $renderPass),
            default => throw new UnknownComponent($component::class),
        };
    }

    /**
     * @param ProfilerDebug $profilerDebug The component; its template reads it.
     * @param RenderPass    $renderPass    The pass its template writes through.
     *
     * @throws UnknownComponent When a child has no template.
     *
     * @return string Its markup, from profiler-debug.phtml.
     */
    private function renderProfilerDebug(ProfilerDebug $profilerDebug, RenderPass $renderPass): string
    {
        $renderPass->open($profilerDebug);
        require __DIR__ . '/profiler-debug.phtml';

        return $renderPass->close();
    }
}
